class Solution {
public:
    int numberOfRoutes(vector<string>& grid, int d) {
        const int MOD = 1000000007;
        int n = grid.size(), m = grid[0].size();
        int reach = (int)sqrt(1LL * d * d - 1);
        vector<int> dp(m, 0);
        for (int row = n - 1; row >= 0; --row) {
            vector<int> incoming(m, 0), prefix(m + 1, 0), next(m, 0);
            if (row == n - 1) {
                for (int j = 0; j < m; ++j) incoming[j] = (grid[row][j] == '.');
            } else {
                for (int j = 0; j < m; ++j)
                    prefix[j + 1] = (prefix[j] + (long long)dp[j]) % MOD;
                for (int j = 0; j < m; ++j) if (grid[row][j] == '.') {
                    int l = max(0, j - reach), r = min(m - 1, j + reach);
                    incoming[j] = (prefix[r + 1] - prefix[l] + MOD) % MOD;
                }
            }
            prefix.assign(m + 1, 0);
            for (int j = 0; j < m; ++j)
                prefix[j + 1] = (prefix[j] + (long long)incoming[j]) % MOD;
            for (int j = 0; j < m; ++j) if (grid[row][j] == '.') {
                int l = max(0, j - d), r = min(m - 1, j + d);
                next[j] = (prefix[r + 1] - prefix[l] + MOD) % MOD;
            }
            dp.swap(next);
        }
        long long ans = 0;
        for (int x : dp) ans += x;
        return ans % MOD;
    }
};
